window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-56bfcee772637ef5"]={"versions": [{"id": "FIG-56bfcee772637ef5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) / Protokoll-Zustandsautomat (<code>PackageManagerStatus</code>).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_SWS_UpdateAndConfigurationManagement</code> (UCM). Das Diagramm modelliert den normativen Lebenszyklus und die Verarbeitungslogik von Software-Paketen (<code>SwPackage</code>) innerhalb des UCM-Servers über das Service Interface <code>ara::ucm::pkgmgr::PackageManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Gewährleistung von transaktionssicheren A/B- oder Staging-Updates (Install, Update, Remove), formaler Abhängigkeitsprüfung, koordinierter Systemrekonfiguration und deterministischer Fehlerbehandlung (Rollback, Revert, Cleanup) gemäß RS_UCM_00024.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Entität:</strong> Zustandsmaschine des UCM Package Managers, nach außen exponiert über das Service-Interface-Feld <code>PackageManagerStatus</code> (Typ <code>PackageManagerStatusType</code>, siehe SWS_UCM_00080).\n</li><li><strong>Zustände (<code>PackageManagerStatus</code>):</strong>\n<ul class=\"fig-list\"><li><code>IDLE</code>: Ruhezustand; kein Software-Paket in Bearbeitung.\n</li><li><code>PROCESSING</code>: Asynchrone Entpackung, Signatur-/Integritätsvalidierung (<code>do / process SW package</code>).\n</li><li><code>READY</code>: Mindestens ein Paket erfolgreich gepuffert/aufbereitet; bereit zur Aktivierung.\n</li><li><code>ACTIVATING</code>: Rekonfiguration und Systemprüfung (<code>do / DependencyCheck</code>).\n</li><li><code>VERIFYING</code>: Validierung des Laufzeitverhaltens und Wiederanlaufs (<code>do / MonitorApplicationRestart</code>).\n</li><li><code>ACTIVATED</code>: Neue Softwareversion erfolgreich aktiviert und verifiziert; wartet auf Abschluss oder Rollback.\n</li><li><code>ROLLING-BACK</code>: Rekonstruktion des vorherigen Softwarestands (<code>do / roll back to old version</code>).\n</li><li><code>ROLLED-BACK</code>: Rollback abgeschlossen; wartet auf Ressourcenbereinigung.\n</li><li><code>CLEANING_UP</code>: Freigabe von Staging-Speicher, temporären Dateien und Session-Handles (<code>do / clean up</code>).\n</li></ul>\n</li><li><strong>Service-Methoden (Trigger):</strong>\n<ul class=\"fig-list\"><li><code>ProcessSwPackage</code>: Startet Paketverarbeitung (SWS_UCM_00086).\n</li><li><code>Cancel</code>: Bricht die laufende Paketverarbeitung ab.\n</li><li><code>RevertProcessedSwPackages</code>: Verwirft alle bisher verarbeiteten Pakete.\n</li><li><code>Activate</code>: Leitet die Aktivierung der bereitstehenden Software-Cluster ein.\n</li><li><code>Rollback</code>: Initiiert das Zurückrollen auf die vorherige Softwareversion.\n</li><li><code>Finish</code>: Schließt den Update- oder Rollback-Vorgang endgültig ab.\n</li></ul>\n</li><li><strong>Bedingungen / Guards:</strong>\n<ul class=\"fig-list\"><li><code>[ProcessedPackages=0]</code>: Keine erfolgreich verarbeiteten Pakete in der aktuellen Sitzung vorhanden.\n</li><li><code>[ProcessedPackages&gt;0]</code>: Mindestens ein Paket erfolgreich im Staging-Bereich validiert.\n</li></ul>\n</li><li><strong>Interne Events / Guard-Signale:</strong> <code>PackageProcessed</code>, <code>Cancelled</code>, <code>OnSuccess</code>, <code>OnFailure</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Normaler Update-Pfad (Happy Path)</h5>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Start im Zustand <code>IDLE</code>.\n</li><li><strong>Paketverarbeitung:</strong> Aufruf von <code>ProcessSwPackage</code> überführt die State Machine nach <code>PROCESSING</code>. Nach Abschluss der internen Verifikation (<code>PackageProcessed</code>) und Erfüllung der Guard <code>[ProcessedPackages&gt;0]</code> erfolgt der Übergang nach <code>READY</code>. Weitere Pakete können durch wiederholten Aufruf von <code>ProcessSwPackage</code> aus <code>READY</code> verarbeitet werden.\n</li><li><strong>Aktivierung:</strong> Aufruf von <code>Activate</code> aus <code>READY</code> wechselt nach <code>ACTIVATING</code>. Die <code>do</code>-Aktivität führt den <code>DependencyCheck</code> zwischen installierten und neuen Clustern durch.\n</li><li><strong>Verifikation:</strong> Bei erfolgreicher Prüfung (<code>OnSuccess</code>) Übergang nach <code>VERIFYING</code>. UCM überwacht via Execution Management (EM) und State Management (SM) den Anlauf der Prozesse (<code>MonitorApplicationRestart</code>).\n</li><li><strong>Abschluss:</strong> Bei fehlerfreiem Anlauf (<code>OnSuccess</code>) Übergang nach <code>ACTIVATED</code>. Der Client quittiert mit <code>Finish</code>, woraufhin <code>CLEANING_UP</code> betreten wird. Nach Beendigung der internen Housekeeping-Routinen erfolgt der automatische Rückfall nach <code>IDLE</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Abbruch- und Fehlerpfade</h5>\n<ul class=\"fig-list\"><li><strong>Cancel während PROCESSING:</strong> \n<ul class=\"fig-list\"><li><code>Cancel</code> feuert als Selbstübergang auf <code>PROCESSING</code>.\n</li><li>Bei Wirksamkeit des Abbruchs (<code>Cancelled</code>): Ist <code>[ProcessedPackages=0]</code>, Rückkehr nach <code>IDLE</code>. Sind bereits vorherige Pakete verarbeitet (<code>[ProcessedPackages&gt;0]</code>), Rückkehr nach <code>READY</code>.\n</li></ul>\n</li><li><strong>Revert vor Aktivierung:</strong>\n<ul class=\"fig-list\"><li><code>RevertProcessedSwPackages</code> kann aus <code>PROCESSING</code> oder <code>READY</code> aufgerufen werden und verzweigt direkt nach <code>CLEANING_UP</code>, um alle Staged Packages zu löschen (SWS_UCM_00151).\n</li></ul>\n</li><li><strong>Fehler während Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Schlägt der <code>DependencyCheck</code> in <code>ACTIVATING</code> fehl (<code>OnFailure</code>), fällt der Automat zurück nach <code>READY</code>. Das System verbleibt in der alten, unveränderten Betriebskonfiguration.\n</li></ul>\n</li><li><strong>Fehler während Verifikation / Expliziter Rollback:</strong>\n<ul class=\"fig-list\"><li>Schlägt <code>MonitorApplicationRestart</code> in <code>VERIFYING</code> fehl (<code>OnFailure</code>) oder wird aus <code>VERIFYING</code> bzw. <code>ACTIVATED</code> die Methode <code>Rollback</code> aufgerufen, wechselt die State Machine nach <code>ROLLING-BACK</code>.\n</li><li>Nach vollständiger Wiederherstellung der Alt-Version wechselt der Automat nach <code>ROLLED-BACK</code>.\n</li><li>Der Aufruf von <code>Finish</code> führt von <code>ROLLED-BACK</code> nach <code>CLEANING_UP</code> und anschließend nach <code>IDLE</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Service-Interface &amp; API-Vertrag (<code>ara::ucm</code>):</strong>\n<ul class=\"fig-list\"><li>Sämtliche Methodenaufrufe (<code>Activate</code>, <code>Rollback</code>, <code>ProcessSwPackage</code>, <code>Finish</code>) sind asynchron als <code>ara::core::Future</code> ausgelegt. \n</li><li>Der Zustand <code>PackageManagerStatus</code> muss als Field mit Notifier bereitgestellt werden, damit UCM-Clients (z. B. OTA-Client / UCM Master) Zustandswechsel reaktiv abfangen können (SWS_UCM_00080, SWS_UCM_00149).\n</li></ul>\n</li><li><strong>Speicher- und Dateisystem-Architektur:</strong>\n<ul class=\"fig-list\"><li>Bis zum Zustand <code>ACTIVATING</code> dürfen keine destruktiven Schreiboperationen auf aktiven Software-Partitionen stattfinden. Alle Operationen in <code>PROCESSING</code> müssen isoliert im Staging-Bereich oder auf inaktiven A/B-Partitionen erfolgen.\n</li><li>In <code>CLEANING_UP</code> müssen Entwickler sicherstellen, dass Mount-Points, File-Descriptors und temporäre Signaturdateien synchron und atomar freigegeben werden, um Deadlocks bei nachfolgenden Updates zu verhindern.\n</li></ul>\n</li><li><strong>Interaktion mit Execution Management (EM) und State Management (SM):</strong>\n<ul class=\"fig-list\"><li>Der Zustand <code>VERIFYING</code> bindet UCM an die Plattform-Health- und State-Management-Mechanismen. Entwickler von Adaptive Applications müssen Startup- und Recovery-Timeouts in den Execution Manifests so dimensionieren, dass <code>MonitorApplicationRestart</code> innerhalb definierter Schwellwerte ein <code>OnSuccess</code> an UCM melden kann.\n</li></ul>\n</li><li><strong>Power-Fail-Safety &amp; Persistenz (SWS_UCM_00151):</strong>\n<ul class=\"fig-list\"><li>Die Zustände <code>ROLLING-BACK</code>, <code>ACTIVATED</code> und <code>ROLLED-BACK</code> müssen nichtflüchtig persistent gesichert sein. Tritt ein Spannungsabfall während <code>ROLLING-BACK</code> auf, muss das Boot-Recovery beim Neustart deterministisch wieder in <code>ROLLING-BACK</code> aufsetzen und den Rollback erzwingen, statt fälschlicherweise in <code>IDLE</code> oder <code>ACTIVATED</code> zu booten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2a7960594f5c7fb3", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) / Protokoll-Zustandsautomat (<code>PackageManagerStatus</code>).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_SWS_UpdateAndConfigurationManagement</code> (UCM). Das Diagramm modelliert den normativen Lebenszyklus und die Verarbeitungslogik von Software-Paketen (<code>SwPackage</code>) innerhalb des UCM-Servers über das Service Interface <code>ara::ucm::pkgmgr::PackageManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Gewährleistung von transaktionssicheren A/B- oder Staging-Updates (Install, Update, Remove), formaler Abhängigkeitsprüfung, koordinierter Systemrekonfiguration und deterministischer Fehlerbehandlung (Rollback, Revert, Cleanup) gemäß RS_UCM_00024.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Entität:</strong> Zustandsmaschine des UCM Package Managers, nach außen exponiert über das Service-Interface-Feld <code>PackageManagerStatus</code> (Typ <code>PackageManagerStatusType</code>, siehe SWS_UCM_00080).\n</li><li><strong>Zustände (<code>PackageManagerStatus</code>):</strong>\n<ul class=\"fig-list\"><li><code>kIdle</code>: Ruhezustand; kein Software-Paket in Bearbeitung.\n</li><li><code>kProcessing</code>: Asynchrone Entpackung, Signatur-/Integritätsvalidierung (<code>do / process SW package</code>).\n</li><li><code>kReady</code>: Mindestens ein Paket erfolgreich gepuffert/aufbereitet; bereit zur Aktivierung.\n</li><li><code>kActivating</code>: Rekonfiguration und Systemprüfung (<code>do / DependencyCheck</code>).\n</li><li><code>kVerifying</code>: Validierung des Laufzeitverhaltens und Wiederanlaufs (<code>do / MonitorApplicationRestart</code>).\n</li><li><code>kActivated</code>: Neue Softwareversion erfolgreich aktiviert und verifiziert; wartet auf Abschluss oder Rollback.\n</li><li><code>kRollingBack</code>: Rekonstruktion des vorherigen Softwarestands (<code>do / roll back to old version</code>).\n</li><li><code>kRolledBack</code>: Rollback erfolgreich abgeschlossen; wartet auf Ressourcenbereinigung.\n</li><li><code>kRollingBackFailed</code>: Fehlerzustand bei fehlgeschlagener Wiederherstellung des Altstands; verharrt bis zu einem erneuten Rollback-Versuch.\n</li><li><code>kCleaningUp</code>: Freigabe von Staging-Speicher, temporären Dateien und Session-Handles (<code>do / clean up</code>).\n</li></ul>\n</li><li><strong>Service-Methoden (Trigger):</strong>\n<ul class=\"fig-list\"><li><code>ProcessSwPackage</code>: Startet die Paketverarbeitung (SWS_UCM_00086).\n</li><li><code>Cancel</code>: Bricht die laufende Paketverarbeitung ab.\n</li><li><code>RevertProcessedSwPackages</code>: Verwirft alle bisher verarbeiteten Pakete.\n</li><li><code>Activate</code>: Leitet die Aktivierung der bereitstehenden Software-Cluster ein.\n</li><li><code>Rollback</code>: Initiiert das Zurückrollen auf die vorherige Softwareversion (aus <code>kVerifying</code>, <code>kActivated</code> oder erneut aus <code>kRollingBackFailed</code>).\n</li><li><code>Finish</code>: Schließt den Update- oder Rollback-Vorgang endgültig ab.\n</li></ul>\n</li><li><strong>Bedingungen / Guards:</strong>\n<ul class=\"fig-list\"><li><code>[ProcessedPackages=0]</code>: Keine erfolgreich verarbeiteten Pakete in der aktuellen Sitzung vorhanden.\n</li><li><code>[ProcessedPackages&gt;0]</code>: Mindestens ein Paket erfolgreich im Staging-Bereich validiert.\n</li></ul>\n</li><li><strong>Interne Events / Guard-Signale:</strong> <code>PackageProcessed</code>, <code>Cancelled</code>, <code>OnSuccess</code>, <code>OnFailure</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Normaler Update-Pfad (Happy Path)</h5>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Start über Pseudozustand <code>Initial</code> in den Zustand <code>kIdle</code>.\n</li><li><strong>Paketverarbeitung:</strong> Aufruf von <code>ProcessSwPackage</code> überführt die State Machine nach <code>kProcessing</code>. Nach interner Verifikation (<code>PackageProcessed</code>) und Erfüllung der Guard <code>[ProcessedPackages&gt;0]</code> erfolgt der Übergang nach <code>kReady</code>. Weitere Pakete können durch wiederholten Aufruf von <code>ProcessSwPackage</code> aus <code>kReady</code> verarbeitet werden.\n</li><li><strong>Aktivierung:</strong> Aufruf von <code>Activate</code> aus <code>kReady</code> wechselt nach <code>kActivating</code>. Die <code>do</code>-Aktivität führt den <code>DependencyCheck</code> zwischen installierten und neuen Clustern durch.\n</li><li><strong>Verifikation:</strong> Bei erfolgreicher Prüfung (<code>OnSuccess</code>) Übergang nach <code>kVerifying</code>. UCM überwacht via Execution Management (EM) und State Management (SM) den Anlauf der Prozesse (<code>MonitorApplicationRestart</code>).\n</li><li><strong>Abschluss:</strong> Bei fehlerfreiem Anlauf (<code>OnSuccess</code>) Übergang nach <code>kActivated</code>. Der Client quittiert mit <code>Finish</code>, woraufhin <code>kCleaningUp</code> betreten wird (<code>do / clean up</code>). Nach Beendigung der Bereinigungsroutinen erfolgt der automatische Rückfall nach <code>kIdle</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Abbruch- und Fehlerpfade</h5>\n<ul class=\"fig-list\"><li><strong>Cancel während kProcessing:</strong>\n<ul class=\"fig-list\"><li><code>Cancel</code> feuert als Selbstübergang auf <code>kProcessing</code>.\n</li><li>Bei Wirksamkeit des Abbruchs (<code>Cancelled</code>): Ist <code>[ProcessedPackages=0]</code>, Rückkehr nach <code>kIdle</code>. Sind bereits vorherige Pakete verarbeitet (<code>[ProcessedPackages&gt;0]</code>), Rückkehr nach <code>kReady</code>.\n</li></ul>\n</li><li><strong>Revert vor Aktivierung:</strong>\n<ul class=\"fig-list\"><li><code>RevertProcessedSwPackages</code> kann aus <code>kProcessing</code> oder <code>kReady</code> aufgerufen werden und verzweigt direkt nach <code>kCleaningUp</code>, um alle Staged Packages zu verwerfen (SWS_UCM_00151).\n</li></ul>\n</li><li><strong>Fehler während Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Schlägt der <code>DependencyCheck</code> in <code>kActivating</code> fehl (<code>OnFailure</code>), fällt der Automat zurück nach <code>kReady</code>. Das System verbleibt in der alten Betriebskonfiguration.\n</li></ul>\n</li><li><strong>Fehler während Verifikation / Expliziter Rollback &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Schlägt <code>MonitorApplicationRestart</code> in <code>kVerifying</code> fehl (<code>OnFailure</code>) oder wird aus <code>kVerifying</code> bzw. <code>kActivated</code> die Methode <code>Rollback</code> aufgerufen, wechselt die State Machine nach <code>kRollingBack</code>.\n</li><li>Bei erfolgreicher Rekonstruktion der Alt-Version (<code>OnSuccess</code>) wechselt der Automat nach <code>kRolledBack</code>. Der Aufruf von <code>Finish</code> führt von <code>kRolledBack</code> nach <code>kCleaningUp</code> und anschließend nach <code>kIdle</code>.\n</li><li>Schlägt die Wiederherstellung in <code>kRollingBack</code> fehl (<code>OnFailure</code>), wechselt die State Machine in den Zustand <code>kRollingBackFailed</code>.\n</li><li>Aus <code>kRollingBackFailed</code> kann über erneuten Methodenaufruf <code>Rollback</code> ein weiterer Wiederherstellungsversuch nach <code>kRollingBack</code> gestartet werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Service-Interface &amp; API-Vertrag (<code>ara::ucm</code>):</strong>\n<ul class=\"fig-list\"><li>Sämtliche Methodenaufrufe (<code>Activate</code>, <code>Rollback</code>, <code>ProcessSwPackage</code>, <code>Finish</code>) sind asynchron als <code>ara::core::Future</code> ausgelegt.\n</li><li>Der Zustand <code>PackageManagerStatus</code> muss als Field mit Notifier bereitgestellt werden, damit UCM-Clients (z. B. OTA-Client / UCM Master) Zustandswechsel reaktiv erfassen können (SWS_UCM_00080, SWS_UCM_00149).\n</li></ul>\n</li><li><strong>Speicher- und Dateisystem-Architektur:</strong>\n<ul class=\"fig-list\"><li>Bis zum Zustand <code>kActivating</code> dürfen keine destruktiven Schreiboperationen auf aktiven Software-Partitionen stattfinden. Alle Operationen in <code>kProcessing</code> müssen isoliert im Staging-Bereich oder auf inaktiven A/B-Partitionen erfolgen.\n</li><li>In <code>kCleaningUp</code> müssen Entwickler sicherstellen, dass Mount-Points, File-Descriptors und temporäre Signaturdateien synchron und atomar freigegeben werden, um Deadlocks bei nachfolgenden Updates zu verhindern.\n</li></ul>\n</li><li><strong>Interaktion mit Execution Management (EM) und State Management (SM):</strong>\n<ul class=\"fig-list\"><li>Der Zustand <code>kVerifying</code> bindet UCM an die Plattform-Health- und State-Management-Mechanismen. Entwickler von Adaptive Applications müssen Startup- und Recovery-Timeouts in den Execution Manifests so dimensionieren, dass <code>MonitorApplicationRestart</code> innerhalb definierter Schwellwerte ein <code>OnSuccess</code> an UCM melden kann.\n</li></ul>\n</li><li><strong>Power-Fail-Safety &amp; Persistenz (SWS_UCM_00151):</strong>\n<ul class=\"fig-list\"><li>Die Zustände <code>kRollingBack</code>, <code>kRollingBackFailed</code>, <code>kActivated</code> und <code>kRolledBack</code> müssen nichtflüchtig persistent gesichert sein. Tritt ein Spannungsabfall oder Abbruch während <code>kRollingBack</code> auf oder wird <code>kRollingBackFailed</code> erreicht, muss das Boot-Recovery beim Neustart deterministisch wieder aufsetzen und erneute Rollback-Versuche ermöglichen, statt in <code>kIdle</code> oder <code>kActivated</code> zu booten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d6c616540dfee50a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) / Protokoll-Zustandsautomat (<code>PackageManagerStatus</code>).\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (Release R21-11), Spezifikation <code>AUTOSAR_SWS_UpdateAndConfigurationManagement</code> (UCM). Das Diagramm modelliert den normativen Lebenszyklus und die Verarbeitungslogik von Software-Paketen (<code>SwPackage</code>) innerhalb des UCM-Servers über das Service Interface <code>ara::ucm::pkgmgr::PackageManagement</code>.\n</li><li><strong>Technischer Zweck:</strong> Gewährleistung von transaktionssicheren A/B- oder Staging-Updates (Install, Update, Remove), formaler Abhängigkeitsprüfung, koordinierter Systemrekonfiguration und deterministischer Fehlerbehandlung (Rollback, Revert, Cleanup) gemäß RS_UCM_00024.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Entität:</strong> Zustandsmaschine des UCM Package Managers, nach außen exponiert über das Service-Interface-Feld <code>PackageManagerStatus</code> (Typ <code>PackageManagerStatusType</code>, siehe SWS_UCM_00080).\n</li><li><strong>Zustände (<code>PackageManagerStatus</code>):</strong>\n<ul class=\"fig-list\"><li><code>kIdle</code>: Ruhezustand; kein Software-Paket in Bearbeitung.\n</li><li><code>kProcessing</code>: Asynchrone Entpackung, Signatur-/Integritätsvalidierung (<code>do / process SW package</code>).\n</li><li><code>kReady</code>: Mindestens ein Paket erfolgreich gepuffert/aufbereitet; bereit zur Aktivierung.\n</li><li><code>kActivating</code>: Rekonfiguration und Systemprüfung (<code>do / DependencyCheck</code>).\n</li><li><code>kVerifying</code>: Validierung des Laufzeitverhaltens und Wiederanlaufs (<code>do / MonitorApplicationRestart</code>).\n</li><li><code>kActivated</code>: Neue Softwareversion erfolgreich aktiviert und verifiziert; wartet auf Abschluss oder Rollback.\n</li><li><code>kRollingBack</code>: Rekonstruktion des vorherigen Softwarestands (<code>do / roll back to old version</code>).\n</li><li><code>kRolledBack</code>: Rollback erfolgreich abgeschlossen; wartet auf Ressourcenbereinigung.\n</li><li><code>kRollingBackFailed</code>: Fehlerzustand bei fehlgeschlagener Wiederherstellung des Altstands; verharrt bis zu einem erneuten Rollback-Versuch.\n</li><li><code>kCleaningUp</code>: Freigabe von Staging-Speicher, temporären Dateien und Session-Handles (<code>do / clean up</code>).\n</li></ul>\n</li><li><strong>Service-Methoden (Trigger):</strong>\n<ul class=\"fig-list\"><li><code>ProcessSwPackage</code>: Startet die Paketverarbeitung (SWS_UCM_00086).\n</li><li><code>Cancel</code>: Bricht die laufende Paketverarbeitung ab.\n</li><li><code>RevertProcessedSwPackages</code>: Verwirft alle bisher verarbeiteten Pakete.\n</li><li><code>Activate</code>: Leitet die Aktivierung der bereitstehenden Software-Cluster ein.\n</li><li><code>Rollback</code>: Initiiert das Zurückrollen auf die vorherige Softwareversion (aus <code>kVerifying</code>, <code>kActivated</code> oder erneut aus <code>kRollingBackFailed</code>).\n</li><li><code>Finish</code>: Schließt den Update- oder Rollback-Vorgang endgültig ab.\n</li></ul>\n</li><li><strong>Bedingungen / Guards:</strong>\n<ul class=\"fig-list\"><li><code>[ProcessedPackages=0]</code>: Keine erfolgreich verarbeiteten Pakete in der aktuellen Sitzung vorhanden.\n</li><li><code>[ProcessedPackages&gt;0]</code>: Mindestens ein Paket erfolgreich im Staging-Bereich validiert.\n</li></ul>\n</li><li><strong>Interne Events / Guard-Signale:</strong> <code>PackageProcessed</code>, <code>Cancelled</code>, <code>OnSuccess</code>, <code>OnFailure</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Normaler Update-Pfad (Happy Path)</h5>\n<ol class=\"fig-list\"><li><strong>Initialisierung:</strong> Start über Pseudozustand <code>Initial</code> in den Zustand <code>kIdle</code>.\n</li><li><strong>Paketverarbeitung:</strong> Aufruf von <code>ProcessSwPackage</code> überführt die State Machine nach <code>kProcessing</code>. Nach interner Verifikation (<code>PackageProcessed</code>) und Erfüllung der Guard <code>[ProcessedPackages&gt;0]</code> erfolgt der Übergang nach <code>kReady</code>. Weitere Pakete können durch wiederholten Aufruf von <code>ProcessSwPackage</code> aus <code>kReady</code> verarbeitet werden.\n</li><li><strong>Aktivierung:</strong> Aufruf von <code>Activate</code> aus <code>kReady</code> wechselt nach <code>kActivating</code>. Die <code>do</code>-Aktivität führt den <code>DependencyCheck</code> zwischen installierten und neuen Clustern durch.\n</li><li><strong>Verifikation:</strong> Bei erfolgreicher Prüfung (<code>OnSuccess</code>) Übergang nach <code>kVerifying</code>. UCM überwacht via Execution Management (EM) und State Management (SM) den Anlauf der Prozesse (<code>MonitorApplicationRestart</code>).\n</li><li><strong>Abschluss:</strong> Bei fehlerfreiem Anlauf (<code>OnSuccess</code>) Übergang nach <code>kActivated</code>. Der Client quittiert mit <code>Finish</code>, woraufhin <code>kCleaningUp</code> betreten wird (<code>do / clean up</code>). Nach Beendigung der Bereinigungsroutinen erfolgt der automatische Rückfall nach <code>kIdle</code>.\n</li></ol>\n<h5 class=\"fig-section-h5\">Abbruch- und Fehlerpfade</h5>\n<ul class=\"fig-list\"><li><strong>Cancel während kProcessing:</strong>\n<ul class=\"fig-list\"><li><code>Cancel</code> feuert als Selbstübergang auf <code>kProcessing</code>.\n</li><li>Bei Wirksamkeit des Abbruchs (<code>Cancelled</code>): Ist <code>[ProcessedPackages=0]</code>, Rückkehr nach <code>kIdle</code>. Sind bereits vorherige Pakete verarbeitet (<code>[ProcessedPackages&gt;0]</code>), Rückkehr nach <code>kReady</code>.\n</li></ul>\n</li><li><strong>Revert vor Aktivierung:</strong>\n<ul class=\"fig-list\"><li><code>RevertProcessedSwPackages</code> kann aus <code>kProcessing</code> oder <code>kReady</code> aufgerufen werden und verzweigt direkt nach <code>kCleaningUp</code>, um alle Staged Packages zu verwerfen (SWS_UCM_00151).\n</li></ul>\n</li><li><strong>Fehler während Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Schlägt der <code>DependencyCheck</code> in <code>kActivating</code> fehl (<code>OnFailure</code>), fällt der Automat zurück nach <code>kReady</code>. Das System verbleibt in der alten Betriebskonfiguration.\n</li></ul>\n</li><li><strong>Fehler während Verifikation / Expliziter Rollback &amp; Fehlerbehandlung:</strong>\n<ul class=\"fig-list\"><li>Schlägt <code>MonitorApplicationRestart</code> in <code>kVerifying</code> fehl (<code>OnFailure</code>) oder wird aus <code>kVerifying</code> bzw. <code>kActivated</code> die Methode <code>Rollback</code> aufgerufen, wechselt die State Machine nach <code>kRollingBack</code>.\n</li><li>Bei erfolgreicher Rekonstruktion der Alt-Version (<code>OnSuccess</code>) wechselt der Automat nach <code>kRolledBack</code>. Der Aufruf von <code>Finish</code> führt von <code>kRolledBack</code> nach <code>kCleaningUp</code> und anschließend nach <code>kIdle</code>.\n</li><li>Schlägt die Wiederherstellung in <code>kRollingBack</code> fehl (<code>OnFailure</code>), wechselt die State Machine in den Zustand <code>kRollingBackFailed</code>.\n</li><li>Aus <code>kRollingBackFailed</code> kann über erneuten Methodenaufruf <code>Rollback</code> ein weiterer Wiederherstellungsversuch nach <code>kRollingBack</code> gestartet werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Service-Interface &amp; API-Vertrag (<code>ara::ucm</code>):</strong>\n<ul class=\"fig-list\"><li>Sämtliche Methodenaufrufe (<code>Activate</code>, <code>Rollback</code>, <code>ProcessSwPackage</code>, <code>Finish</code>) sind asynchron als <code>ara::core::Future</code> ausgelegt.\n</li><li>Der Zustand <code>PackageManagerStatus</code> muss als Field mit Notifier bereitgestellt werden, damit UCM-Clients (z. B. OTA-Client / UCM Master) Zustandswechsel reaktiv erfassen können (SWS_UCM_00080, SWS_UCM_00149).\n</li></ul>\n</li><li><strong>Speicher- und Dateisystem-Architektur:</strong>\n<ul class=\"fig-list\"><li>Bis zum Zustand <code>kActivating</code> dürfen keine destruktiven Schreiboperationen auf aktiven Software-Partitionen stattfinden. Alle Operationen in <code>kProcessing</code> müssen isoliert im Staging-Bereich oder auf inaktiven A/B-Partitionen erfolgen.\n</li><li>In <code>kCleaningUp</code> müssen Entwickler sicherstellen, dass Mount-Points, File-Descriptors und temporäre Signaturdateien synchron und atomar freigegeben werden, um Deadlocks bei nachfolgenden Updates zu verhindern.\n</li></ul>\n</li><li><strong>Interaktion mit Execution Management (EM) und State Management (SM):</strong>\n<ul class=\"fig-list\"><li>Der Zustand <code>kVerifying</code> bindet UCM an die Plattform-Health- und State-Management-Mechanismen. Entwickler von Adaptive Applications müssen Startup- und Recovery-Timeouts in den Execution Manifests so dimensionieren, dass <code>MonitorApplicationRestart</code> innerhalb definierter Schwellwerte ein <code>OnSuccess</code> an UCM melden kann.\n</li></ul>\n</li><li><strong>Power-Fail-Safety &amp; Persistenz (SWS_UCM_00151):</strong>\n<ul class=\"fig-list\"><li>Die Zustände <code>kRollingBack</code>, <code>kRollingBackFailed</code>, <code>kActivated</code> und <code>kRolledBack</code> müssen nichtflüchtig persistent gesichert sein. Tritt ein Spannungsabfall oder Abbruch während <code>kRollingBack</code> auf oder wird <code>kRollingBackFailed</code> erreicht, muss das Boot-Recovery beim Neustart deterministisch wieder aufsetzen und erneute Rollback-Versuche ermöglichen, statt in <code>kIdle</code> oder <code>kActivated</code> zu booten.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-56bfcee772637ef5", "to": "FIG-2a7960594f5c7fb3", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Zustand kRollingBackFailed:</strong> Neuer Zustand <code>kRollingBackFailed</code> zur expliziten Behandlung fehlgeschlagener Rollback-Versuche hinzugefügt.\n</li><li><strong>Transition kRollingBack -&gt; kRollingBackFailed:</strong> Neue Transition bei Fehler während des Rollback-Vorgangs mit Trigger/Event <code>OnFailure</code> ergänzt.\n</li><li><strong>Transition kRollingBackFailed -&gt; kRollingBack:</strong> Neue Transition zur erneuten Durchführung des Rollbacks über den Methodenaufruf <code>Rollback</code> hinzugefügt.\n</li><li><strong>Transition kRollingBack -&gt; kRolledBack:</strong> Der zuvor unbeschriftete Übergang wurde explizit mit dem internen Event <code>OnSuccess</code> annotiert.\n</li><li><strong>Zustandsbezeichner (Naming-Konvention):</strong> Umstellung aller Zustandsnamen auf lowerCamelCase mit vorangestelltem <code>k</code>-Präfix (<code>IDLE</code> -&gt; <code>kIdle</code>, <code>PROCESSING</code> -&gt; <code>kProcessing</code>, <code>READY</code> -&gt; <code>kReady</code>, <code>ACTIVATING</code> -&gt; <code>kActivating</code>, <code>VERIFYING</code> -&gt; <code>kVerifying</code>, <code>ACTIVATED</code> -&gt; <code>kActivated</code>, <code>ROLLING-BACK</code> -&gt; <code>kRollingBack</code>, <code>ROLLED-BACK</code> -&gt; <code>kRolledBack</code>, <code>CLEANING_UP</code> -&gt; <code>kCleaningUp</code>).\n</li></ul>"}, {"from": "FIG-2a7960594f5c7fb3", "to": "FIG-d6c616540dfee50a", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
